function createPaginator(fetchFn, options = {}) {
  const pageSize = options.pageSize || 10;
  let items = [];
  let loading = false;
  let hasMore = true;
  let error = null;
  let currentPage = 0;

  async function loadMore() {
    if (loading || !hasMore) return;

    loading = true;
    error = null;

    try {
      const nextPage = currentPage + 1;
      const result = await fetchFn(nextPage, pageSize);
      const data = result.data || [];
      items = [...items, ...data];
      currentPage = nextPage;
      hasMore = result.hasMore !== undefined ? result.hasMore : data.length >= pageSize;
    } catch (e) {
      error = e;
    } finally {
      loading = false;
    }
  }

  function reset() {
    items = [];
    loading = false;
    hasMore = true;
    error = null;
    currentPage = 0;
  }

  return {
    get items() { return items; },
    get loading() { return loading; },
    get hasMore() { return hasMore; },
    get error() { return error; },
    get currentPage() { return currentPage; },
    loadMore,
    reset
  };
}
